def find_kinks(x0, d, T=30.0, n_grid=60):
    """Return t-values of kinks of g(t)=f(x0+t d) in [-T, T]."""
    g = lambda t: f(x0 + t * d)
    ts = np.linspace(-T, T, n_grid + 1)
    kinks = []
    VTOL, STOL, MINW = 1e-10, 1e-6, 1e-8

    def slopes_at(t, ft, dl):
        return (ft - g(t - dl)) / dl, (g(t + dl) - ft) / dl

    def search(a, b, fa, fb, sa, sb, depth=0):
        # sa: slope just right of a, sb: slope just left of b
        if abs(sa - sb) < STOL:
            m = 0.5 * (a + b)
            if (
                abs(g(m) - 0.5 * (fa + fb)) < VTOL
                and abs(fb - fa - sa * (b - a)) < VTOL * 10
            ):
                return  # linear on [a, b]
